// 1. Get values from memory, or set them if it's the first time
var filter = flow.get("f") || "All";
var limit = flow.get("l") || 10;

// 2. If a dropdown was clicked, update the specific memory slot
if (msg.topic === "filter") {
    filter = msg.payload;
    flow.set("f", filter);
}
else if (msg.topic === "limit") {
    limit = msg.payload;
    flow.set("l", limit);
}
// If msg.topic is "refresh" (from the inject node), 
// we ignore the payload and use the memory.

// 3. Build the URL using the variables we just finalized
msg.url = "http://host.docker.internal:8000/api/v1/sensors?limit=" + limit;

if (filter !== "All") {
    msg.url += "&type=" + filter;
}

return msg;

var logs = msg.payload.data; // Reaching into your professional API wrapper

if (!logs || !Array.isArray(logs)) {
    return null;
}

// Map exactly to the keys the table expects
msg.payload = logs.slice(0, 10).map(row => ({
    "Time": new Date(row.timestamp).toLocaleTimeString(),
    "Room": row.room,
    "Sensor": row.sensor,
    "Value": typeof row.value === 'object' ? JSON.stringify(row.value) : row.value,
    "Status": row.status
}));

return msg;

